import { describe, it, expect } from 'vitest';
import * as git from 'isomorphic-git';
import { recordEvent, replayEvents, getDatabase, createTestContext } from '@hive/core';
import type { HiveContext } from '@hive/core';

const branch = 'hive-test';
async function bootstrap(): Promise<{ ctx: HiveContext; dir: string }> {
  const dir = '/test-repo';
  const ctx = await createTestContext(dir);
  ctx.fs.mkdirSync(dir, { recursive: true });
  ctx.fs.mkdirSync(`${dir}/.hive`, { recursive: true });
  await git.init({ fs: ctx.fs as any, dir, defaultBranch: 'main' });
  await git.setConfig({ fs: ctx.fs as any, dir, path: 'user.name', value: 'Test User' });
  await git.setConfig({ fs: ctx.fs as any, dir, path: 'user.email', value: 'test@example.com' });
  ctx.fs.writeFileSync(`${dir}/README.md`, '# Test');
  await git.add({ fs: ctx.fs as any, dir, filepath: 'README.md' });
  await git.commit({ fs: ctx.fs as any, dir, message: 'Initial commit',
    author: { name: 'Test User', email: 'test@example.com' } });
  await git.branch({ fs: ctx.fs as any, dir, ref: branch });
  return { ctx, dir };
}

describe('recordEvent materialises add events (P6 gap)', () => {
  it('leaves the node recoverable from the log after the watermark advances', async () => {
    const { ctx } = await bootstrap();

    // Record an 'add' event only. recordEvent appends the commit and advances the
    // watermark; the caller does NOT separately insert the node (the disk-full /
    // process-killed witness). The event is now durably in the git log.
    await recordEvent(ctx, { type: 'add', nodeType: 'decision', content: 'x', confidence: 90 }, branch);

    // Give the system every chance to materialise the durable event: replay from the
    // log. If the watermark is only valid once the node is materialised, the node must
    // now exist in the database.
    await replayEvents(ctx, branch);

    const db = getDatabase(ctx);
    const row = db.prepare('SELECT title FROM nodes WHERE branch = ? AND node_type = ?')
      .get(branch, 'decision') as { title: string } | undefined;

    expect(row?.title).toBe('x');
  });
});
